package com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.verify;import com.bct.ngtpa.apiservice.application.dto.auth.login.account.LoginSessionAccount;import com.bct.ngtpa.apiservice.application.dto.session.authenticated.AuthenticatedSessionId;import java.util.*;public record VerifyLoginOtpResult(VerifyLoginOtpStatus status,Integer remainingVerifyAttempts,boolean clearAuthFlowCookie,List<LoginSessionAccount> accounts,AuthenticatedSessionId authenticatedSessionId){public VerifyLoginOtpResult{Objects.requireNonNull(status);accounts=accounts==null?List.of():List.copyOf(accounts);if(status==VerifyLoginOtpStatus.ACCOUNTS_READY&&(accounts.isEmpty()||authenticatedSessionId==null))throw new IllegalArgumentException("ACCOUNTS_READY requires accounts and authenticated session");if(status!=VerifyLoginOtpStatus.ACCOUNTS_READY&&(!accounts.isEmpty()||authenticatedSessionId!=null))throw new IllegalArgumentException("Failure result cannot carry accounts or session");}public VerifyLoginOtpResult(VerifyLoginOtpStatus status,Integer remainingVerifyAttempts,boolean clearAuthFlowCookie,List<LoginSessionAccount> accounts){this(status,remainingVerifyAttempts,clearAuthFlowCookie,accounts,null);}public VerifyLoginOtpResult(VerifyLoginOtpStatus status,Integer remainingVerifyAttempts,boolean clearAuthFlowCookie){this(status,remainingVerifyAttempts,clearAuthFlowCookie,List.of(),null);}@Override public String toString(){return "VerifyLoginOtpResult[status="+status+", remainingVerifyAttempts="+remainingVerifyAttempts+", clearAuthFlowCookie="+clearAuthFlowCookie+", accountCount="+accounts.size()+", authenticatedSessionId=<redacted>]";}}
